# ═══════════════════════════════════════════════════════════════
# gitlab-upsert-issues.ps1 — Herramienta de carga/actualización de issues en GitLab
#
# Carga los roadmaps MD (funcionalidades F1-F5 + mejoras C/K/L/R/A/D)
# como issues estandarizados en el proyecto sales-ai-platform/wibsite.
#
# USO:
#   1. Editar los bloques Add-Issue de este script (agregar/modificar issues)
#   2. Ejecutar desde la raíz del repo wibsite:
#        powershell -NoProfile -ExecutionPolicy Bypass -File .\scripts\gitlab\gitlab-upsert-issues.ps1
#      O bien (para preservar UTF-8 del script sin BOM):
#        $c = [IO.File]::ReadAllText('.\scripts\gitlab\gitlab-upsert-issues.ps1', [Text.Encoding]::UTF8); Invoke-Expression $c
#   3. Verificar salida: todas las líneas "OK #iid" (HTTP 2xx).
#
# REGLAS:
#   - NO usar Invoke-RestMethod para enviar texto con acentos: PS 5.1 corrompe
#     el body UTF-8 (mojibake). Este script usa curl.exe + JSON escapado \uXXXX.
#   - El token se toma del remote gitlab (git config remote.gitlab.url).
#   - El mapeo issue->iid es POR ORDEN de llamadas Add-Issue: mantener el orden
#     de las llamadas si se re-ejecuta para actualizar (PUT) en vez de duplicar.
#   - Detalle completo del flujo: docs/GITLAB-ISSUE-WORKFLOW.md
#
# Generado: 27/08/2026 · última ejecución exitosa: carga de 77 issues (#17-#93)
# ═══════════════════════════════════════════════════════════════
$ErrorActionPreference = 'Continue'
$base = 'http://127.0.0.1:9080/api/v4'
$projectId = 1
$remote = git config --get remote.gitlab.url
$token = ($remote -replace '.*oauth2:(.*)@.*', '$1')
$headers = @{ 'PRIVATE-TOKEN' = $token }
$TMPDIR = $env:TEMP

function ConvertTo-AsciiJson {
  param($Obj)
  $json = $Obj | ConvertTo-Json -Compress -Depth 8
  $sb = New-Object System.Text.StringBuilder
  foreach ($ch in $json.ToCharArray()) {
    $code = [int]$ch
    if ($code -gt 0x7E) {
      [void]$sb.Append('\u')
      [void]$sb.Append($code.ToString('X4'))
    } else {
      [void]$sb.Append($ch)
    }
  }
  return $sb.ToString()
}

function Invoke-GitLab {
  param([string]$Method, [string]$Path, [hashtable]$Body = $null)
  if ($Body) {
    $json = ConvertTo-AsciiJson $Body
    $tmp = Join-Path $TMPDIR ("gl-" + [guid]::NewGuid().ToString('N') + '.json')
    [System.IO.File]::WriteAllText($tmp, $json, (New-Object System.Text.UTF8Encoding($false)))
    $out = & curl.exe -s -w "`nHTTPCODE:%{http_code}" -X $Method "$base$Path" -H "PRIVATE-TOKEN: $token" -H "Content-Type: application/json" --data-binary "@$tmp"
    Remove-Item $tmp -Force -ErrorAction SilentlyContinue
    $statusLine = ($out | Select-Object -Last 1)
    if ($statusLine -match 'HTTPCODE:(\d+)') { return $Matches[1] }
    return '0'
  } else {
    $out = & curl.exe -s -w "`nHTTPCODE:%{http_code}" -X $Method "$base$Path" -H "PRIVATE-TOKEN: $token"
    $statusLine = ($out | Select-Object -Last 1)
    if ($statusLine -match 'HTTPCODE:(\d+)') { return $Matches[1] }
    return '0'
  }
}

# ── 1. Mapear milestones existentes (ids 2-11 por orden de creación) ──
$allMs = Invoke-RestMethod -Uri "$base/projects/$projectId/milestones?per_page=100" -Headers $headers
$myMs = @($allMs | Where-Object { $_.id -ge 2 -and $_.id -le 11 } | Sort-Object id)
Write-Output "Milestones a reparar: $($myMs.Count)"

$milestones = @(
  @{ title = 'Oleada 0 - Cimientos de datos';              start = '2026-08-27'; due = '2026-09-04'; desc = 'PG primario, índices, normalización y archivado de conversaciones. Prerequisito de todo el roadmap.' },
  @{ title = 'Oleada 1 - Ciclo de vida del lead (F1)';     start = '2026-09-07'; due = '2026-09-18'; desc = 'Etapas claras (primer contacto -> comprador), transiciones validadas, perfil 360 y dedup.' },
  @{ title = 'Oleada 2 - Grupos y segmentos (F2/F3)';      start = '2026-09-21'; due = '2026-10-02'; desc = 'Grupos manuales con agrupador IA + segmentos dinámicos con job continuo.' },
  @{ title = 'Oleada 3 - Campañas inteligentes';           start = '2026-10-05'; due = '2026-10-16'; desc = 'Audiencia por segmento, bloqueo opt-out, A/B, eventos, dry-run, rate-limit.' },
  @{ title = 'Oleada 4 - Respuestas automáticas';          start = '2026-10-19'; due = '2026-10-30'; desc = 'Bienvenida/fuera de horario, snippets, comandos, handoff inmediato, validación del grafo.' },
  @{ title = 'Oleada 5 - Copiloto y asignación';           start = '2026-11-02'; due = '2026-11-13'; desc = 'Copiloto IA en chat, handoff con contexto, asignación automática, resúmenes.' },
  @{ title = 'Oleada 6 - Calendario y seguimiento (F4)';   start = '2026-11-16'; due = '2026-11-27'; desc = 'Motor de cadencias ejecutable, eventos automáticos, vista por fecha con cards por grupo, SLAs.' },
  @{ title = 'Oleada 7 - Cierre: auditoría y UX';          start = '2026-11-30'; due = '2026-12-11'; desc = 'Atribución, feedback al score, predicción, webhooks, auditoría completa, GDPR.' },
  @{ title = 'Oleada 8 - Consolidación (F5)';              start = '2026-12-14'; due = '2026-12-23'; desc = 'Agente plantillero + suite e2e integral + actualización documental completa.' },
  @{ title = 'Pospuestos - Dependencias externas';         start = $null;        due = $null;        desc = 'Requerirá Twenty bidireccional, SaaS multi-tenant o APIs externas. Se reactivan cuando esas dependencias existan.' }
)
$global:msMap = @{}
for ($i = 0; $i -lt $milestones.Count; $i++) {
  $id = $myMs[$i].id
  $m = $milestones[$i]
  $body = @{ title = $m.title; description = $m.desc }
  if ($m.start) { $body.start_date = $m.start }
  if ($m.due) { $body.due_date = $m.due }
  $status = Invoke-GitLab 'PUT' "/projects/$projectId/milestones/$id" $body
  $global:msMap[$m.title] = $id
  if ($status -match '^2') { Write-Output "MS reparado: [$id] $($m.title)" } else { Write-Output "MS ERROR [$id] => HTTP $status" }
}

