foreach ($l in $labels) {
  $enc = [uri]::EscapeDataString($l.name)
  $body = @{ new_name = $l.name; color = $l.color; description = $l.description }
  $status = Invoke-GitLab 'PUT' "/projects/$projectId/labels/$enc" $body
  if ($status -match '^2') { Write-Output "LB reparada: $($l.name)" } else { Write-Output "LB ERROR: $($l.name) => HTTP $status" }
}

# ── 4. Mapear issues existentes (iid 17-93 en orden de creación) ──
$allIssues = Invoke-RestMethod -Uri "$base/projects/$projectId/issues?per_page=100&sort=asc" -Headers $headers
$myIssues = @($allIssues | Where-Object { $_.iid -ge 17 -and $_.iid -le 93 } | Sort-Object iid)
Write-Output "Issues a reparar: $($myIssues.Count)"
$global:issueCounter = 0

function Add-Issue {
  param([hashtable]$i)
  $idx = $global:issueCounter
  $global:issueCounter++
  if ($idx -ge $myIssues.Count) { Write-Output "SKIP (sin iid): $($i.id)"; return }
  $iid = $myIssues[$idx].iid
  $milestoneId = $global:msMap[$i.milestone]
  $labelList = @(
    "area::$($i.area)",
    "priority::$($i.priority)",
    "status::$($i.status)",
    "type::$($i.type)"
  )
  if ($i.roadmap) { $labelList += $i.roadmap | ForEach-Object { "roadmap::$($_)" } }
  $labelsStr = ($labelList -join ',')

  $alcanceTxt = ($i.alcance | ForEach-Object { "- $_" }) -join "`n"
  $depsTxt = if ($i.deps.Count -gt 0) { $i.deps -join ', ' } else { '—' }
  $desbloqueaTxt = if ($i.desbloquea.Count -gt 0) { $i.desbloquea -join ', ' } else { '—' }
  $archTxt = ($i.archivos | ForEach-Object { "- $_" }) -join "`n"
  $checksTxt = ($i.checks | ForEach-Object { "- [ ] $_" }) -join "`n"
  $refsTxt = ($i.refs | ForEach-Object { "- $_" }) -join "`n"

  $desc = @"
## Contexto
$($i.contexto)

## Alcance
$alcanceTxt

## Relaciones
- Depende de: $depsTxt
- Desbloquea: $desbloqueaTxt
- Origen: $($i.origen)
- Oleada: $($i.milestone)

## Implementación objetivo
$archTxt

## Verificación (DoD)
$checksTxt

## Referencias
$refsTxt

## KPI
$($i.kpi)

---
*Issue generado desde los roadmaps MD el 27/08/2026. Estandar: contexto + alcance + relaciones + DoD + referencias.*
"@

  $title = "[$($i.prefix)] $($i.id) - $($i.title)"
  $body = @{ title = $title; description = $desc; labels = $labelsStr }
  if ($milestoneId) { $body.milestone_id = $milestoneId }
  $status = Invoke-GitLab 'PUT' "/projects/$projectId/issues/$iid" $body
  if ($status -match '^2') { Write-Output "OK  #$iid $title" } else { Write-Output "FAIL #$iid $title => HTTP $status" }
}

